-- sinonimos_busqueda: 5 filas

-- Alinear las secuencias identity con los ids ya insertados arriba.
select setval(pg_get_serial_sequence('public.familias_motor','id'), coalesce((select max(id) from public.familias_motor),1), true);
select setval(pg_get_serial_sequence('public.modelos_comerciales','id'), coalesce((select max(id) from public.modelos_comerciales),1), true);
select setval(pg_get_serial_sequence('public.sinonimos_busqueda','id'), coalesce((select max(id) from public.sinonimos_busqueda),1), true);